def write_file(name, b64content):
    data = base64.b64decode(b64content)
    with open(name, "wb") as f:
        f.write(data)
    print(f"  wrote {name} ({len(data):,} bytes)")


if __name__ == "__main__":
    main()
    write_file("app.js", APP_JS_B64)
    write_file("index.html", INDEX_HTML_B64)
    write_file("style.css", STYLE_CSS_B64)
    print()
    print("Done! Ramanandi Mode fixes applied:")
    print("  - Bangla jap text language now works for Ramanandi Mode")
    print("  - Daily/Lifetime target rows are now full-width and horizontal")
    print()
    print("Original files were saved as app.js.bak / index.html.bak / style.css.bak")
    print()
    print("Next steps:")
    print("  git add app.js index.html style.css")
    print("  git commit -m \"Fix Ramanandi Bangla text + horizontal target rows\"")
    print("  git push origin main")
    print("  npm run build:apk")
